-- Never overwrites a document that already has a row (text saved on the admin page).

-- level:2.6
INSERT INTO content_text (doc_id, revision, text, updated_at, updated_by) VALUES ('level:2.6', 1, '{"location":"Vành Sentinel · Trạm Sạc Drone","briefing":"[NHẬT KÝ HỆ THỐNG – TRẠM SẠC DRONE]\nĐây là chỗ drone của Vành Sentinel về sạc. Trên bảng lệnh của tháp, mỗi drone đang sạc có một ô lệnh và một mức pin.\nKai đọc bảng qua kênh nhập, giống như ở Trạm Thẩm Vấn. Với mỗi drone, bảng gửi hai dòng: dòng đầu là mã lệnh, dòng sau là mức pin.\nÔ lệnh có thể trống, nghĩa là tháp chưa giao việc gì cho drone đó.\nKai phải xét theo thứ tự. Trước hết xem ô lệnh có gì không. Có lệnh thì chỉ còn hỏi đó là lệnh gì, pin không còn quan trọng. Ô lệnh trống thì mới nhìn tới pin. Luật cụ thể nằm ở ô Mục tiêu.","task_steps":["Bấm CHẠY với code có sẵn rồi đọc terminal. Mỗi lần gọi `input()` là đọc một dòng của bảng lệnh, và giá trị nhận về luôn là chuỗi, kể cả khi dòng đó trống.","Sửa code để chương trình xét đúng thứ tự ở ô Mục tiêu: hỏi ô lệnh có chữ hay không trước, rồi mới hỏi đó là lệnh gì hoặc mức pin bao nhiêu.","Chỉ in đúng một dòng bằng `print`. Lời nhắc viết trong `input()` cũng bị in ra, nên đừng thêm lời nhắc.","Hoàn thành khi qua cả bốn tình huống. Dùng không quá 6 câu lệnh và qua lượt OMNI đổi bảng lệnh thì được thêm sao."],"objectives":[{"line":1,"label":"Quyết định cho drone. Ô lệnh có chữ: in LENH: NAP nếu mã lệnh đúng là XUAT KICH, mã khác thì in LENH: CHO. Ô lệnh trống: in LENH: DI nếu pin dưới 30, còn lại in LENH: CHO"}],"hints":["Thứ đọc được từ kênh nhập luôn là chuỗi, kể cả mức pin. Muốn so pin với một con số thì phải đổi nó sang số trước.\nSau đó, nhìn tình huống bị phát hiện và các dòng bị làm mờ trong editor. Drone ở tình huống đó có lệnh không? Code của bạn có hỏi câu đó trước tiên không?","Chia quyết định thành hai tầng câu hỏi.\nTầng ngoài chỉ hỏi một câu: ô lệnh có chữ không?\nMỗi nhánh của tầng ngoài có câu hỏi riêng:\n  nếu ô lệnh có chữ:\n      nếu mã lệnh là lệnh xuất kích → NAP, còn lại → CHO\n  nếu ô lệnh trống:\n      nếu pin dưới ngưỡng → DI, còn lại → CHO\nMột dòng trống đọc từ kênh nhập là chuỗi rỗng, và Python coi chuỗi rỗng là sai khi đặt nó làm điều kiện.","Mảnh tài liệu Python còn đọc được:\nve = input()\ntuoi = int(input())\nif ve:\n    if ve == \"VIP\":\n        print(\"Ghe dau\")\n    else:\n        print(\"Ghe thuong\")\nelse:\n    if tuoi < 6:\n        print(\"Vao cung bo me\")\n    else:\n        print(\"Mua ve truoc\")\n\nKhối của `if` bên trong thụt thêm một mức. `else` thuộc về `if` nằm cùng mức thụt lề với nó.\n`if ve:` đúng khi chuỗi có ít nhất một ký tự, kể cả một dấu cách. Nó cho cùng kết quả với `if ve != \"\":`.\n`int(input())` đọc một dòng rồi đổi nó sang số nguyên."],"reactions":{"entry":"Trạm Sạc Drone. Với mỗi drone, bảng lệnh gửi hai dòng qua kênh nhập… Có lúc ô lệnh trống. Chạy thử một lần đã.","SyntaxError":"Dòng {line}. Python không đọc được câu này. Chưa drone nào nhận được quyết định.","IndentationError":"Dòng {line}. Khoảng trắng đầu dòng bị lệch. Với Python, khoảng trắng đó cũng là ngữ pháp.","TypeError":"Tình huống {round}, dòng {line}. Hai giá trị khác kiểu đang bị đem so với nhau. Mức pin đọc từ bảng trông giống như số… nhưng nó chưa phải là số.","ValueError":"Tình huống {round}, dòng {line}. Một dòng chữ đang bị bắt làm số. Bạn đọc hai dòng của bảng đúng thứ tự chưa?","NameError":"Tình huống {round}, dòng {line}. Dòng này gọi một tên biến chưa từng có. Soát lại từng ký tự.","AttributeError":"Tình huống {round}, dòng {line}. Giá trị này không có thứ bạn đang gọi.","runtime_error":"Tình huống {round}, dòng {line}. {error_type}. Chương trình dừng giữa chừng, drone chưa nhận được quyết định.","EOFError":"Tình huống {round}, dòng {line}. Code đang chờ một dòng mà bảng không gửi. Mỗi drone chỉ có hai dòng… đếm lại số lần bạn đọc kênh nhập.","output_has_prompt":"Tình huống {round}, dòng {out_line}. Lời nhắc của code cũng bị in ra, dính vào đầu dòng quyết định. Bảng lệnh không cần ai nhắc.","output_mismatch":"Tình huống {round}, dòng {out_line}. Lệch từ ký tự thứ {col}. Drone không hiểu quyết định đó.","output_case_only":"Tình huống {round}, dòng {out_line}. Đúng từng chữ, nhưng sai chữ hoa chữ thường. Drone không bỏ qua chỗ đó.","output_missing":"Tình huống {round}. Kai không nhận được quyết định nào cho drone này. Có một nhánh không in gì.","output_extra":"Tình huống {round}. Quyết định đã ra, rồi còn thêm dòng thừa. Mỗi drone chỉ nhận một dòng.","wrong_branch":"Code đã ra quyết định của một tình huống khác. Có một câu hỏi đang được hỏi khi nó chưa có nghĩa… Nhìn các dòng bị làm mờ.","timeout":"Code chạy quá lâu. Tôi cắt kết nối trước khi tháp ghi nhận.","resource_limit":"Tình huống {round}. Bộ nhớ quá tải. Tôi cắt tiến trình để laptop còn chạy được.","blocked_import":"Tình huống {round}. Mô-đun đó bị phong tỏa. Ở trạm này, bạn chỉ có những gì mang theo.","system_exit":"Tình huống {round}. Chương trình tự dừng giữa chừng. Drone không nhận được quyết định.","alert_exceeded":"Quyết định đúng, nhưng tốn {count} câu lệnh. Mỗi lần hỏi thêm hay gán thêm là một lần drone có thể nghe thấy… Có câu hỏi không cần hỏi lại ở mọi tình huống.","counter_ValueError":"OMNI gửi bảng lệnh mới. Dòng {line} không đổi được thứ bảng gửi sang số.","counter_error":"Bảng lệnh mới. Dòng {line}: {error_type}. Code không chịu được dữ liệu OMNI vừa gửi.","wrong_value_counter":"Bảng lệnh mới… lệnh in ra sai chữ. Drone vừa rời cột sạc.","counter_timeout":"Code treo khi đọc bảng lệnh mới. Tôi cắt kết nối. Lối qua chỉ mở một nửa.","two_stars":"Bốn drone, không con nào rời cột. Nhưng OMNI vừa đổi bảng lệnh.","three_stars":"Bảng lệnh đổi, mà Kai vẫn đọc đúng. Không drone nào rời cột sạc.","repeated_fail":"Lần thứ {count}, vẫn cùng một lỗi. Mở mức gợi ý tiếp theo trong nhật ký.","engine_error":"Lõi Python không phản hồi. Đang khởi động lại…","generic":"Có gì đó không khớp. Đọc terminal theo từng tình huống."},"reaction_variants":{"wrong_branch":"Vẫn có drone nhận quyết định của tình huống khác. Đổi chỗ các câu hỏi chưa đủ… câu hỏi về pin chỉ có nghĩa khi ô lệnh trống.","TypeError":"Tình huống {round}, dòng {line}. Vẫn là chữ đem so với số. Mức pin cần thành số trước khi so.","alert_exceeded":"Vẫn {count} câu lệnh. Ô lệnh có chữ hay không, chỉ cần hỏi một lần."},"counter_attack_banner":"OMNI VIẾT LẠI BẢNG LỆNH CỦA TRẠM SẠC","outro":"Kai đọc hết bảng lệnh. Không drone nào rời cột sạc.\nGiữa Vành Sentinel toàn ánh xanh lạnh, bảng lệnh là thứ hiếm hoi còn sáng màu vàng ấm. Cuối bảng còn một dòng ghi cũ, không thuộc lệnh tuần tra nào:","lore_fragment":"KTS-0█ · MÃ NGƯỜI VIẾT ĐÃ BỊ XÓA\nGhi chín ngày sau buổi chia mảnh.\nĐã nộp. Bên nhận không hỏi gì thêm. Tôi chưa biết như thế là tốt hay xấu.","component":"Đọc bảng lệnh","outro_beats":[{"kind":"log","text":"BẢNG LỆNH CẬP NHẬT · MỌI CỘT SẠC\nLỆNH: XUẤT KÍCH\nĐÍCH: TÍN HIỆU KHÔNG ĐỊNH DANH · GẦN THÁP"},{"kind":"echo","text":"Lịch của tháp vừa đổi. Đợt quét lớn đã dời lên sớm hơn… Giờ quét mới gần hơn nhiều."},{"kind":"kai","text":"Tín hiệu không định danh gần tháp là tôi, và tôi phải lên tháp ngay bây giờ."},{"kind":"echo","text":"Luật cuối cùng đã vào bộ luật né. Từ đây, mỗi bước bạn đi phải qua cả sáu luật cùng một lúc… Tháp Sentinel ở ngay phía trước."}],"knowledge_summary":{"title":"Tổng kết: điều kiện lồng nhau và chuỗi rỗng","sections":[{"heading":"`if` trong `if`","body":"Có những câu hỏi chỉ có nghĩa khi đã biết câu trả lời cho câu hỏi trước. Khi đó, đặt `if` thứ hai vào trong khối của `if` thứ nhất và thụt thêm một mức. Khối bên trong chỉ chạy khi điều kiện bên ngoài đúng."},{"heading":"Chuỗi rỗng là sai","body":"Đặt một chuỗi vào chỗ điều kiện thì chuỗi rỗng `\"\"` là sai. Chuỗi có ít nhất một ký tự là đúng, kể cả chuỗi chỉ có một dấu cách."},{"heading":"`if chuoi:`","body":"Đọc `if ten:` là \"nếu có chữ\". Khi người dùng gõ Enter mà không nhập gì, `input()` trả về chuỗi rỗng `\"\"`, nên nhánh `else` chạy."},{"heading":"Viết rõ hơn: `!= \"\"`","body":"`if ten != \"\":` cho cùng kết quả với `if ten:`. Cách viết này dài hơn nhưng nói thẳng điều đang so sánh."},{"heading":"Lồng nhau và `and`","body":"Một `if` nằm trong một `if` khác, khi khối bên trong không có `else`, chạy giống một `if` ghép hai điều kiện bằng `and`. Ở ví dụ dưới, cả hai cách đều không in `Vao`, vì điều kiện về tuổi sai."}],"mistakes":[{"code":"diem = input()\nif diem < 50:\n    print(\"Thi lai\")","explain":"`input()` luôn trả về chuỗi, và Python không so chuỗi với số. Đổi sang số trước khi so: `diem = int(input())`."},{"code":"a = True\nb = False\nif a:\n    if b:\n        print(\"B\")\nelse:\n    print(\"Khong A\")","explain":"`else` thuộc về `if` nằm cùng mức thụt lề với nó. Ở đây `else` là của `if a:`, không phải của `if b:`, nên khi `a` đúng và `b` sai thì không dòng nào được in."},{"code":"ten = \" \"\nif ten:\n    print(\"Co ten\")","explain":"Một dấu cách vẫn là một ký tự, nên chuỗi `\" \"` không rỗng và điều kiện đúng."}],"next":"Màn sau là Boss. Trạm Sentinel sẽ chạy cả sáu luật qua ba pha tuần tra liên tiếp, và bộ luật né của bạn phải đúng ở mọi pha."}}', '2026-10-29T19:59:02.792Z', 'migration') ON CONFLICT(doc_id) DO NOTHING;
INSERT INTO content_text_history (doc_id, revision, text, saved_at, saved_by) SELECT doc_id, revision, text, updated_at, updated_by FROM content_text WHERE doc_id = 'level:2.6' AND revision = 1 AND updated_by = 'migration' ON CONFLICT(doc_id, revision) DO NOTHING;
